const uor01Text = $('Extract UOR-01 Text').first().json.data || '';
const uor03Text = $('Extract UOR-03 Text').first().json.data || '';
const uor04Text = $('Extract UOR-04 Text').first().json.data || '';
const uor05Text = $('Extract UOR-05 Text').first().json.data || '';
const uor06Text = $('Extract UOR-06 Text').first().json.data || '';

// Reused convention: HIGH_THRESHOLD = 60, identical to UOR-01's own Section 26
// interpretation gate (Validation node) -- read live before this was designed,
// not re-derived, so a score is meaningfully comparable across modules
// (Sections 7/24).
const HIGH_THRESHOLD = 60;
const GATE_FORMULA_VERSION = 'uor09-v1-productization-gate-2026-09-09';

function parseLines(text) {
  const out = [];
  let failures = 0;
  text.split('\n').filter((l) => l.trim().length > 0).forEach((line) => {
    try { out.push(JSON.parse(line)); } catch (e) { failures++; }
  });
  return { records: out, failures };
}

const uor01 = parseLines(uor01Text);
const uor03 = parseLines(uor03Text);
const uor04 = parseLines(uor04Text);
const uor05 = parseLines(uor05Text);
const uor06 = parseLines(uor06Text);

const uor01ById = new Map();
uor01.records.forEach((r) => {
  const existing = uor01ById.get(r.opportunity_id);
  if (!existing || String(r.date_stored) > String(existing.date_stored)) {
    uor01ById.set(r.opportunity_id, r);
  }
});

const uor04ById = new Map(uor04.records.map((r) => [r.opportunity_id, r]));

const uor03ById = new Map();
uor03.records.forEach((r) => {
  const existing = uor03ById.get(r.opportunity_id);
  if (!existing || String(r.computed_at) > String(existing.computed_at)) {
    uor03ById.set(r.opportunity_id, r);
  }
});

const uor05ById = new Map();
uor05.records.forEach((r) => {
  const existing = uor05ById.get(r.opportunity_id);
  if (!existing || String(r.computed_at) > String(existing.computed_at)) {
    uor05ById.set(r.opportunity_id, r);
  }
});

const tagsByOppId = new Map();
uor06.records.forEach((row) => {
  (row.member_opportunity_ids || []).forEach((id) => {
    if (!tagsByOppId.has(id)) tagsByOppId.set(id, []);
    tagsByOppId.get(id).push({ tag: row.tag, frequency_count: row.frequency_count, cluster_status: row.cluster_status });
  });
});

const allOppIds = [...uor01ById.keys()];

const results = allOppIds.map((id) => {
  const u1 = uor01ById.get(id);
  const u3 = uor03ById.get(id) || null;
  const u4 = uor04ById.get(id) || null;
  const u5 = uor05ById.get(id) || null;
  const tags = tagsByOppId.get(id) || [];

  const isSynthetic = u1.evidence?.is_synthetic === true;
  const complianceFlag = u1.compliance_review_required === true;

  let gate_status;
  let opportunity_score = null;
  let evidence_confidence = null;

  if (!u4 || typeof u4.reconciled_opportunity_score !== 'number' || typeof u4.evidence_confidence_v2_latest !== 'number') {
    gate_status = 'NOT_YET_SCORED';
  } else {
    opportunity_score = u4.reconciled_opportunity_score;
    evidence_confidence = u4.evidence_confidence_v2_latest;
    const highOpp = opportunity_score >= HIGH_THRESHOLD;
    const highEvid = evidence_confidence >= HIGH_THRESHOLD;
    if (highOpp && highEvid) gate_status = 'HIGH-PRIORITY CANDIDATE';
    else if (highOpp && !highEvid) gate_status = 'PROMISING — REQUIRES VALIDATION';
    else if (!highOpp && highEvid) gate_status = 'RELIABLY LOW PRIORITY';
    else gate_status = 'INSUFFICIENT / LOW PRIORITY';
  }

  let productization_tier;
  let tier_reason;
  if (isSynthetic) {
    // Cost-governance addition (Section 12): never spend a real LLM call
    // productizing a known-fake test fixture, regardless of its score.
    productization_tier = 'NO_DRAFT';
    tier_reason = 'SYNTHETIC_TEST_EXCLUDED';
  } else if (gate_status === 'HIGH-PRIORITY CANDIDATE') {
    productization_tier = 'FULL_PRODUCTIZATION_DRAFT';
    tier_reason = 'HIGH_SCORE_HIGH_EVIDENCE';
  } else if (gate_status === 'PROMISING — REQUIRES VALIDATION') {
    productization_tier = 'LIGHT_VALIDATION_DRAFT';
    tier_reason = 'HIGH_SCORE_LOW_EVIDENCE';
  } else if (gate_status === 'NOT_YET_SCORED') {
    productization_tier = 'NO_DRAFT';
    tier_reason = 'NOT_YET_SCORED_BY_UOR04';
  } else {
    productization_tier = 'NO_DRAFT';
    tier_reason = gate_status === 'RELIABLY LOW PRIORITY' ? 'LOW_SCORE_HIGH_EVIDENCE' : 'LOW_SCORE_LOW_EVIDENCE';
  }

  // Section 25/26 compliance override -- absolute, applied last, never
  // bypassed by score. No LLM call ever made for this tier.
  if (complianceFlag) {
    productization_tier = 'COMPLIANCE_REVIEW_ONLY';
    tier_reason = 'COMPLIANCE_REVIEW_REQUIRED_OVERRIDE';
  }

  const needs_llm_draft = productization_tier === 'FULL_PRODUCTIZATION_DRAFT' || productization_tier === 'LIGHT_VALIDATION_DRAFT';

  return {
    opportunity_id: id,
    is_synthetic: isSynthetic,
    compliance_review_required: complianceFlag,
    compliance_keywords_detected: u1.compliance_keywords_detected || [],
    opportunity_score,
    evidence_confidence,
    gate_status,
    productization_tier,
    tier_reason,
    needs_llm_draft,
    opportunity_title: u1.raw_signal?.opportunity_title ?? null,
    problem: u1.raw_signal?.problem ?? null,
    demand_signal: u1.raw_signal?.demand_signal ?? null,
    evidence_notes: u1.evidence?.evidence_notes ?? null,
    source: u1.source ?? null,
    source_url: u1.source_url ?? null,
    corroboration_status: u3?.corroboration_status ?? null,
    matched_capability_domains: u5?.matched_capability_domains ?? [],
    matched_stack_tools: u5?.matched_stack_tools ?? [],
    capability_match_status: u5?.capability_match_status ?? null,
    automation_potential_pct: u5?.automation_potential_pct ?? null,
    demand_tags: tags,
    gate_formula_version: GATE_FORMULA_VERSION,
  };
});

return results.map((r) => ({ json: r }));

const rec = $json;

const isFull = rec.productization_tier === 'FULL_PRODUCTIZATION_DRAFT';

const FULL_FIELDS = [
  'customer_problem', 'target_customer', 'proposed_solution', 'deliverables',
  'fulfillment_workflow', 'estimated_fulfillment_time', 'required_tools',
  'estimated_cost', 'pricing_hypothesis', 'pricing_tiers', 'recurring_upsells',
  'portfolio_demo_concept', 'proof_of_concept_requirements', 'sales_proposition',
  'competitive_differentiation', 'risks', 'next_validation_experiment',
];
const LIGHT_FIELDS = [
  'customer_problem', 'target_customer', 'proposed_solution',
  'risks', 'proof_of_concept_requirements', 'next_validation_experiment',
];

const fields = isFull ? FULL_FIELDS : LIGHT_FIELDS;

// Existing Section 3 stack -- the model should prefer these tools and only
// name something outside this list if the record genuinely requires it.
const EXISTING_STACK = ['MacBook', 'Claude app', 'Claude Code', 'Anthropic API', 'n8n (self-hosted)', 'MCP', 'KIE.ai', 'ElevenLabs', 'ChatGPT', 'Grok', 'CapCut', 'Canva', 'Xcode'];

const context = {
  opportunity_id: rec.opportunity_id,
  source: rec.source,
  source_url: rec.source_url,
  opportunity_title: rec.opportunity_title,
  problem: rec.problem,
  demand_signal: rec.demand_signal,
  evidence_notes: rec.evidence_notes,
  known_opportunity_score: rec.opportunity_score,
  known_evidence_confidence: rec.evidence_confidence,
  known_matched_capability_domains: rec.matched_capability_domains,
  known_matched_stack_tools: rec.matched_stack_tools,
  known_automation_potential_pct: rec.automation_potential_pct,
  known_demand_cluster_tags: rec.demand_tags,
  known_corroboration_status: rec.corroboration_status,
};

const tierInstruction = isFull
  ? 'This opportunity is a HIGH-PRIORITY CANDIDATE (high score, high evidence confidence). Produce a full productization draft.'
  : 'This opportunity is PROMISING — REQUIRES VALIDATION (high score, but evidence confidence is not yet strong). Produce a LIGHTER draft focused on what would need to be validated before any investment — do NOT include pricing, sales language, or a go-to-market pitch; this is not ready for that yet.';

const promptText = `Here is one opportunity record that has already passed a deterministic scoring gate (score and evidence confidence were calculated by code, not by you -- do not recompute or restate them as your own judgment):

${JSON.stringify(context, null, 2)}

${tierInstruction}

The known automation percentage (${rec.automation_potential_pct ?? 'not available'}%) was already computed deterministically upstream -- do NOT include an automation_percentage field, it will be attached separately.

Existing available tool stack (prefer these; only name something outside this list if the opportunity genuinely requires it, and say so explicitly): ${EXISTING_STACK.join(', ')}.

Produce a JSON object with exactly these fields: ${fields.join(', ')}.

For any field where the record does not contain enough information to support a real answer, use the literal string "insufficient information" for that field rather than inventing a plausible-sounding number or claim. Fields expecting a list should be JSON arrays of short strings. pricing_tiers (if requested) should be an array of objects like {"tier_name": "...", "price": "...", "includes": "..."}.`;

return {
  json: {
    ...rec,
    prompt_text: promptText,
    prompt_fields_requested: fields,
  },
};

const aiResponse = $json;
const rec = $('Build Productization Prompt').item.json;

function stripCodeFences(text) {
  return String(text)
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

const rawText = aiResponse?.content?.[0]?.text ?? null;

let parsed = null;
let parseError = null;

if (rawText) {
  try {
    parsed = JSON.parse(stripCodeFences(rawText));
  } catch (err) {
    parseError = err.message;
  }
} else {
  parseError = 'No text content found in AI response';
}

const requiredFields = rec.prompt_fields_requested || [];
const missingFields = parsed ? requiredFields.filter((k) => !(k in parsed)) : [...requiredFields];
const draftValid = parsed !== null && missingFields.length === 0;

// automation_percentage is a deterministic passthrough, never LLM-generated
// (see UOR-09-Build-Log.md) -- attach it here, after parsing, not requested
// of the model at all.
const productization_draft = draftValid
  ? { ...parsed, automation_percentage: rec.automation_potential_pct }
  : null;

// NOTE (bug fix): the Anthropic node's own output ({content: [...]}) does NOT
// carry through the upstream item's other fields -- unlike Code nodes, it
// replaces $json entirely with just its own response. Every field this node
// needs from before the AI call (opportunity_id, productization_tier, etc.)
// must be re-fetched from the named upstream node via $('Build Productization
// Prompt').item, exactly like UOR-01's own Structured Output node already does
// for its AI Extraction step. The first build of this node assumed spread-through
// would work and silently produced records with no opportunity_id at all,
// each then misclassified downstream as draft_generation_status: NOT_ATTEMPTED
// even though the real Anthropic call had actually succeeded -- caught via file
// verification, not the execution's own reported 'success' status.
return {
  json: {
    ...rec,
    productization_draft,
    draft_generation_status: draftValid ? 'GENERATED' : 'PARSE_FAILED',
    draft_parse_error: parseError,
    draft_missing_fields: missingFields,
    draft_raw_response: rawText,
  },
};

const items = $input.all();

const results = items.map((item) => {
  const r = item.json;
  const tier = r.productization_tier;

  let productization_draft;
  let draft_generation_status;
  let llm_model_used = null;
  let llm_call_made = false;

  if (tier === 'FULL_PRODUCTIZATION_DRAFT' || tier === 'LIGHT_VALIDATION_DRAFT') {
    // These came through the LLM branch -- Parse Productization Draft already
    // set productization_draft / draft_generation_status on the item.
    productization_draft = r.productization_draft ?? null;
    draft_generation_status = r.draft_generation_status ?? 'PARSE_FAILED';
    llm_call_made = true;
    llm_model_used = tier === 'FULL_PRODUCTIZATION_DRAFT' ? 'claude-sonnet-5' : 'claude-haiku-4-5-20251001';
  } else if (tier === 'COMPLIANCE_REVIEW_ONLY') {
    productization_draft = {
      notice: 'COMPLIANCE REVIEW REQUIRED — see Section 25/26 of the master project instructions. Requires human/professional clearance before any productization, proposed solution, pricing, or sales language is developed for this opportunity.',
      compliance_keywords_detected: r.compliance_keywords_detected || [],
    };
    draft_generation_status = 'NOT_ATTEMPTED';
  } else {
    // NO_DRAFT
    productization_draft = null;
    draft_generation_status = 'NOT_ATTEMPTED';
  }

  return {
    opportunity_id: r.opportunity_id,
    source: r.source,
    source_url: r.source_url,
    opportunity_title: r.opportunity_title,
    is_synthetic: r.is_synthetic,
    compliance_review_required: r.compliance_review_required,
    opportunity_score: r.opportunity_score,
    evidence_confidence: r.evidence_confidence,
    gate_status: r.gate_status,
    productization_tier: tier,
    tier_reason: r.tier_reason,
    productization_draft,
    draft_generation_status,
    llm_call_made,
    llm_model_used,
    matched_capability_domains: r.matched_capability_domains,
    matched_stack_tools: r.matched_stack_tools,
    demand_tags: r.demand_tags,
    gate_formula_version: r.gate_formula_version,
    requires_human_approval_for_execution: true,
    computed_at: new Date().toISOString(),
  };
});

const fileText = results.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    record_count: results.length,
    tier_breakdown: results.reduce((acc, r) => { acc[r.productization_tier] = (acc[r.productization_tier] || 0) + 1; return acc; }, {}),
    llm_calls_made: results.filter((r) => r.llm_call_made).length,
    draft_status_breakdown: results.reduce((acc, r) => { acc[r.draft_generation_status] = (acc[r.draft_generation_status] || 0) + 1; return acc; }, {}),
    file_text: fileText,
  },
}];
